//! `anvil prereqs script`: `init.sh` and `init.ps1`, thin wrappers around `anvil prereqs check`.

use std::fs;
use std::path::Path;

use anvil_core::config::AnvilConfig;
use anyhow::{Context, Result};

use crate::ui;

const INIT_SH: &str = r#"#!/bin/sh
# Generated by `anvil prereqs script`. Checks that this machine has what the project needs.
# Usage: ./init.sh [--json] [--subrepo NAME]. Exit code 0: ready, 1: a required item is missing or outdated.
cd "$(dirname "$0")" || exit 1

if ! command -v anvil >/dev/null 2>&1; then
  cat >&2 <<'MSG'
anvil is not installed or not on PATH.

Install it from an Anvil checkout:
  scripts/install.sh                          # Linux and macOS, builds from source
  cargo install --path crates/anvil-cli       # any platform
  scripts/install.sh --from-release           # no Rust toolchain; needs `gh auth login`
On Windows run scripts/install.ps1 (add -FromRelease for a prebuilt binary).
MSG
  exit 127
fi

anvil prereqs check "$@"
exit $?
"#;

const INIT_PS1: &str = r#"# Generated by `anvil prereqs script`. Checks that this machine has what the project needs.
# Usage: .\init.ps1 [--json] [--subrepo NAME]. Exit code 0: ready, 1: a required item is missing or outdated.
Set-Location -LiteralPath $PSScriptRoot

if (-not (Get-Command anvil -ErrorAction SilentlyContinue)) {
    [Console]::Error.WriteLine(@"
anvil is not installed or not on PATH.

Install it from an Anvil checkout:
  scripts\install.ps1                          # Windows, builds from source (add -FromRelease for a prebuilt binary)
  cargo install --path crates/anvil-cli        # any platform
On Linux and macOS run scripts/install.sh.
"@)
    exit 127
}

& anvil prereqs check @args
exit $LASTEXITCODE
"#;

/// Writes `init.sh` and `init.ps1` into `out` (default: the repository root).
pub(super) fn write_scripts(root: &Path, out: Option<&Path>) -> Result<()> {
    let dir = out.unwrap_or(root);
    fs::create_dir_all(dir).with_context(|| format!("failed to create {}", dir.display()))?;
    for (name, body) in [("init.sh", INIT_SH), ("init.ps1", INIT_PS1)] {
        let path = dir.join(name);
        fs::write(&path, body).with_context(|| format!("failed to write {}", path.display()))?;
        make_executable(&path)?;
        println!("{} {}", ui::green("wrote"), path.display());
    }
    if dir == root {
        allow_in_root_hygiene(root)?;
    }
    Ok(())
}

#[cfg(unix)]
fn make_executable(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;
    fs::set_permissions(path, fs::Permissions::from_mode(0o755))?;
    Ok(())
}

#[cfg(not(unix))]
fn make_executable(_path: &Path) -> Result<()> {
    Ok(())
}

/// Existing configs store their own `root_allowlist`; make sure the wrappers do not trip the root rule.
fn allow_in_root_hygiene(root: &Path) -> Result<()> {
    if !AnvilConfig::path(root).exists() {
        return Ok(());
    }
    let mut config = AnvilConfig::load(root)?;
    let missing: Vec<&str> = ["init.sh", "init.ps1", "init.cmd"]
        .into_iter()
        .filter(|f| !config.root_allowlist.iter().any(|a| a == f))
        .collect();
    if missing.is_empty() {
        return Ok(());
    }
    config.root_allowlist.extend(missing.iter().map(|f| (*f).to_owned()));
    config.save(root)?;
    println!("added {} to root_allowlist", missing.join(", "));
    Ok(())
}
